mapper.select:
SELECT EXISTS(
    SELECT 1 FROM user_follows
    WHERE follower_id = #{followerId,javaType=java.util.UUID,jdbcType=OTHER}
      AND following_id = #{followingId,javaType=java.util.UUID,jdbcType=OTHER}
)

SELECT f.follower_id FROM user_follows f JOIN users u ON u.id = f.follower_id WHERE f.following_id = #{authorId,javaType=java.util.UUID,jdbcType=OTHER}
AND f.follower_id > #{afterFollowerId,javaType=java.util.UUID,jdbcType=OTHER}
AND u.deleted_at IS NULL AND u.account_status = 'ACTIVE' AND u.account_type = 'HUMAN'
AND LOWER(TRIM(u.username)) IN
#{username}
AND NOT EXISTS ( SELECT 1 FROM user_blocks b WHERE (b.blocker_id = f.follower_id AND b.blocked_id = f.following_id) OR (b.blocker_id = f.following_id AND b.blocked_id = f.follower_id)) ORDER BY f.follower_id LIMIT #{limit}

