UPDATE users
SET time_zone = #{timeZone}
WHERE id = #{id,javaType=java.util.UUID,jdbcType=OTHER} AND deleted_at IS NULL
  AND time_zone IS DISTINCT FROM #{timeZone}

UPDATE users
SET birth_year = #{birthYear}, updated_at = #{updatedAt}
WHERE id = #{id,javaType=java.util.UUID,jdbcType=OTHER} AND deleted_at IS NULL

